# Reproduce extension summaries and within-seed OMP contrasts.
extsum=[]
for (e,s),g in itertools.groupby(sorted([r for r in extra if r['role']=='same_mask_continuation_not_independent_initialization'],key=lambda r:(r['architecture'],r['sparsity'])),lambda r:(r['architecture'],r['sparsity'])):
 g=list(g);x=np.array([float(r['sparse_minus_dense_ce']) for r in g]);extsum.append(dict(architecture=e,sparsity=s,n_seeds=len(g),mean_gap=x.mean(),sd=x.std(ddof=1),ci95_low=x.mean()-stats.t.ppf(.975,len(x)-1)*stats.sem(x),ci95_high=x.mean()+stats.t.ppf(.975,len(x)-1)*stats.sem(x),min_gap=x.min(),max_gap=x.max(),at_or_better_dense=sum(x<=0)))
