def table(rows,fields):
 return '| '+' | '.join(fields)+' |\n| '+' | '.join(['---']*len(fields))+' |\n'+'\n'.join('| '+' | '.join(f'{float(r[f]):.5f}' if isinstance(r.get(f),(float,np.floating)) else str(r.get(f,'')) for f in fields)+' |' for r in rows)
for r in summary:
 for f in ['mean_gap','sd','ci95_low','ci95_high']:r[f]=float(r[f])
# Cross-cell sign agreement is descriptive; sparsities and architectures share source seeds.
